import{_ as d,o as a,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Закон о Защите Прав Потребителей","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0042-消费者保护法.md","filePath":"ru/0042-消费者保护法.md"}'),l={name:"ru/0042-消费者保护法.md"};function e(o,t,h,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="закон-о-защите-прав-потребителеи" tabindex="-1">Закон о Защите Прав Потребителей <a class="header-anchor" href="#закон-о-защите-прав-потребителеи" aria-label="Permalink to &quot;Закон о Защите Прав Потребителей&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>42</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Права потребителей, Справедливая торговля, Антимошенничество, Ответственность за продукцию, Симбиотический рынок</td></tr></tbody></table><h2 id="i-цель-законодательства-и-сфера-применения" tabindex="-1">I. Цель законодательства и сфера применения <a class="header-anchor" href="#i-цель-законодательства-и-сфера-применения" aria-label="Permalink to &quot;I. Цель законодательства и сфера применения&quot;">​</a></h2><p><em>Закон о Защите Прав Потребителей</em> — один из ключевых законов правовой системы Симбиотической Цивилизации Якоря. Вместе с <em>Симбиотическим Трудовым Законом</em> он составляет две опоры экономической жизни. Настоящий Закон направлен на защиту законных прав и интересов всех потребителей во Вселенной Хэнъюань, регулирование рыночных сделок, поддержание справедливого, честного и симбиотического рыночного порядка и предотвращение ущемления прав и интересов существ хищническими коммерческими практиками.</p><p>Настоящий Закон применяется ко всем потребителям во Вселенной Хэнъюань, которые приобретают или используют товары либо получают услуги для удовлетворения личных или семейных бытовых потребностей, а также к операторам, предоставляющим потребителям товары или услуги. Межплоскостные сделки также подпадают под действие настоящего Закона, но могут разрабатываться правила применения с учётом различий плоскостей.</p><h2 id="ii-основные-права-потребителеи" tabindex="-1">II. Основные права потребителей <a class="header-anchor" href="#ii-основные-права-потребителеи" aria-label="Permalink to &quot;II. Основные права потребителей&quot;">​</a></h2><p>Настоящий Закон устанавливает, что потребители пользуются следующими девятью основными правами:</p><table tabindex="0"><thead><tr><th>Право</th><th>Содержание</th></tr></thead><tbody><tr><td>Право на гарантию безопасности</td><td>Потребители пользуются правом на ненанесение ущерба их личной и имущественной безопасности при покупке, использовании товаров и получении услуг</td></tr><tr><td>Право знать правду</td><td>Потребители имеют право знать подлинное состояние приобретаемых или используемых товаров или получаемых услуг, включая состав, эффективность, риски и т.д.</td></tr><tr><td>Право самостоятельного выбора</td><td>Потребители имеют право самостоятельно выбирать товары или услуги, сравнивать, оценивать и отбирать, отказываться от принудительных сделок</td></tr><tr><td>Право на справедливую сделку</td><td>Потребители имеют право на получение справедливых условий сделки: гарантия качества, разумные цены, точные измерения и т.д.</td></tr><tr><td>Право на возмещение по закону</td><td>Потребители, понёсшие личный или имущественный ущерб при покупке, использовании товаров или получении услуг, имеют право на возмещение в соответствии с законом</td></tr><tr><td>Право на объединение для защиты прав</td><td>Потребители имеют право создавать или вступать в потребительские организации в соответствии с законом для защиты своих законных прав и интересов</td></tr><tr><td>Право на получение знаний</td><td>Потребители имеют право получать знания и информацию о потреблении и защите прав потребителей</td></tr><tr><td>Право на уважение</td><td>При покупке, использовании товаров и получении услуг потребители пользуются правом на уважение личного достоинства, национальных обычаев и традиций</td></tr><tr><td>Право на контроль</td><td>Потребители имеют право контролировать товары и услуги, а также работу по защите прав потребителей, вносить критические замечания и предложения</td></tr></tbody></table><h2 id="iii-обязанности-операторов" tabindex="-1">III. Обязанности операторов <a class="header-anchor" href="#iii-обязанности-операторов" aria-label="Permalink to &quot;III. Обязанности операторов&quot;">​</a></h2><p>При предоставлении потребителям товаров или услуг операторы обязаны выполнять следующие обязанности:</p><ol><li><strong>Обязанность законной деятельности</strong>: операторы обязаны соблюдать Конституцию и законы и вести предпринимательскую деятельность в пределах утверждённого объёма.</li><li><strong>Обязанность гарантии безопасности</strong>: операторы обязаны обеспечивать соответствие предоставляемых товаров или услуг требованиям безопасности личности и имущества, давать правдивые разъяснения и чёткие предупреждения о товарах и услугах, способных создавать угрозу безопасности.</li><li><strong>Обязанность правдивой информации</strong>: операторы обязаны предоставлять потребителям правдивую информацию о товарах или услугах и не допускать ложной или вводящей в заблуждение рекламы. Культивационные товары и услуги обязаны правдиво указывать границы эффективности и потенциальные риски.</li><li><strong>Обязанность гарантии качества</strong>: операторы обязаны гарантировать, что при нормальном использовании товаров или получении услуг предоставляемые товары или услуги обладают должными качеством, характеристиками, назначением и сроком действия.</li><li><strong>Обязанность справедливой сделки</strong>: операторы не вправе посредством типовых условий, уведомлений, заявлений, объявлений в магазине и т.п. устанавливать несправедливые или неразумные положения, исключающие или ограничивающие права потребителей, уменьшающие или освобождающие от ответственности оператора, либо усугубляющие ответственность потребителя.</li><li><strong>Обязанность послепродажного обслуживания</strong>: операторы обязаны в соответствии с государственными правилами или договорённостями с потребителями нести ответственность за ремонт, замену, возврат и другое послепродажное обслуживание.</li><li><strong>Обязанность защиты конфиденциальности</strong>: операторы обязаны защищать персональную информацию и данные сознания потребителей; без согласия потребителя не допускается их сбор, использование или разглашение.</li></ol><h2 id="iv-разрешение-споров-и-юридическая-ответственность" tabindex="-1">IV. Разрешение споров и юридическая ответственность <a class="header-anchor" href="#iv-разрешение-споров-и-юридическая-ответственность" aria-label="Permalink to &quot;IV. Разрешение споров и юридическая ответственность&quot;">​</a></h2><p>При возникновении спора о правах потребителя между потребителем и оператором он может быть разрешён следующими путями:</p><ul><li>Переговоры и примирение с оператором</li><li>Обращение за посредничеством в потребительскую организацию</li><li>Жалоба в соответствующий административный орган</li><li>Обращение в арбитражный орган в соответствии с арбитражным соглашением, достигнутым с оператором</li><li>Подача иска в Симбиотический Суд</li></ul><p>Операторы, нарушившие положения настоящего Закона и ущемившие законные права и интересы потребителей, несут следующую ответственность:</p><table tabindex="0"><thead><tr><th>Правонарушение</th><th>Юридическая ответственность</th></tr></thead><tbody><tr><td>Предоставление дефектных товаров или услуг, причинивших вред</td><td>Нести ответственность за возмещение, включая медицинские расходы, компенсацию за потерю заработка, компенсацию за инвалидность и т.д.</td></tr><tr><td>Мошеннические действия</td><td>Увеличить возмещение по требованию потребителя в трёхкратном размере цены приобретённого товара или стоимости полученных услуг</td></tr><tr><td>Ложная реклама</td><td>Предписание прекратить правонарушение, устранить последствия и уплатить штраф</td></tr><tr><td>Принудительные сделки</td><td>Предписание исправить нарушение, возвратить необоснованные платежи и уплатить штраф</td></tr><tr><td>Нарушение конфиденциальности потребителя</td><td>Нести компенсацию морального вреда; при серьёзных обстоятельствах — уголовная ответственность</td></tr></tbody></table><h2 id="v-потребительские-организации-и-общественныи-контроль" tabindex="-1">V. Потребительские организации и общественный контроль <a class="header-anchor" href="#v-потребительские-организации-и-общественныи-контроль" aria-label="Permalink to &quot;V. Потребительские организации и общественный контроль&quot;">​</a></h2><p>Государство поощряет и поддерживает все организации и индивидов в осуществлении общественного контроля за действиями, наносящими ущерб законным правам и интересам потребителей. Ассоциация потребителей — это социальная организация, законно созданная для общественного контроля за товарами и услугами и защиты законных прав и интересов потребителей, выполняющая следующие функции:</p><ol><li>Предоставление потребителям информации о потреблении и консультационных услуг</li><li>Участие в контроле и проверке товаров и услуг соответствующими административными органами</li><li>Доведение до сведения соответствующих административных органов вопросов о законных правах и интересах потребителей, запросы и предложения</li><li>Приём жалоб потребителей, расследование и посредничество по предметам жалоб</li><li>Поддержка пострадавших потребителей в подаче исков против действий, наносящих ущерб законным правам и интересам потребителей</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Закон о Защите Прав Потребителей</em> — страж рыночного порядка Симбиотической Цивилизации Якоря. Предоставляя потребителям полные права, ограничивая поведение операторов и создавая многоканальный механизм разрешения споров, он обеспечивает движение рыночных сделок по пути справедливости, честности и симбиоза, не позволяя коммерческой сфере стать новой питательной средой хищнических практик.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>41-共生劳动法 (Симбиотический Трудовой Закон)</li><li>47-反垄断法 (Антимонопольный Закон)</li><li>36-社会结构与阶层流动 (Социальная Структура и Классовая Мобильность)</li></ul>',23)])])}const u=d(l,[["render",e]]);export{_ as __pageData,u as default};
